    for (int index = 1; index <= count; index++) prefix[index] = prefix[index - 1] + input.number();
    int[] queue = new int[count + 1];
    int head = 0;
    int tail = 0;
    int best = count + 1;
    for (int end = 0; end <= count; end++) {
